class TTL:
    FILM = 60 * 60 * 24 * 7      # 7 days
    POPULAR = 60 * 60 * 6        # 6 hours
    TOP_RATED = 60 * 60 * 24     # 1 day
    UPCOMING = 60 * 60 * 12      # 12 hours
    NEW = 60 * 60 * 6            # 6 hours
    TRENDING = 60 * 60 * 3       # 3 hours
    GENRES = 60 * 60 * 24 * 30   # 30 days
    CREDITS = 60 * 60 * 24 * 7   # 7 days